const math=(p,inline=false)=>inline?`<span class="sax-exact-inline">${mathHTML(p.latex,false)}</span>`:`<div class="sax-matrix" tabindex="0">${mathHTML(p.latex,true)}</div>`;
const formula=s=>`<div class="sax-formula" tabindex="0">${mathHTML(s,true)}</div>`,yes=x=>x?"yes":"no";
const table=(title,heads,rows)=>`<div class="sax-scroll" tabindex="0"><table><caption>${esc(title)}</caption><thead><tr>${heads.map(x=>'<th scope="col">'+esc(x)+'</th>').join('')}</tr></thead><tbody>${rows.map(row=>'<tr>'+row.map((x,i)=>i?'<td>'+x+'</td>':'<th scope="row">'+x+'</th>').join('')+'</tr>').join('')}</tbody></table></div>`;
function exampleHTML(e){return`<article class="sax-ant-example"><h5>${esc(e.title)}</h5><p><strong>Fixed counterexample · spin 1/2 · dimension 4 · k=${esc(JSON.stringify(e.k))} · dimensionless model energies</strong></p><p>${esc(e.description)}</p><p>Preserves the stated Hamiltonian symmetry: ${yes(e.preservesHamiltonian)}; degeneracy present: ${yes(e.spectrum.hasDegeneracy)}。</p><p>Eigenvalues: ${e.spectrum.eigenvalues.map(s=>math(s,true)).join('，')}</p><details data-sax-native="${e.id}"><summary>Expand the matrices and residuals of this fixed counterexample</summary><p>Matrix part of the symmetry operator:</p>${math(e.symmetryMatrix)}<p>Square of this operator:</p>${math(e.operatorSquare)}<p>Counterexample Hamiltonian:</p>${math(e.hamiltonian)}<p>Symmetry residual:</p>${math(e.symmetryResidual)}${e.comparisonAntiunitaryResidual?"<p>Residual for antiunitary A acting on the same Hamiltonian:</p>"+math(e.comparisonAntiunitaryResidual):''}${formula(e.formula)}<p>${esc(e.scope)}</p></details></article>`;}
export function antitranslationResultHTML(r,{stage=1}={}){
 if(antitranslationModel(r).status!=='available')return"<p role=\"alert\">The antitranslation result is incomplete. Calculate again.</p>";
 const b=r.basis,k=r.momentum,t=r.translation,a=r.antiunitary,d=r.decision;
 let html="<h4>1. Identify the state spaces and the returning momentum</h4><p>The square's phase depends only on the longitudinal component, but time reversal reverses all three components. Check every component before discussing a partner at the same k.</p><p>"+esc(b.convention)+"</p><p>Ordered basis: <code data-math-ignore>"+b.order.map(esc).join('，')+"</code>; dimension "+b.dimension+'。</p><p>'+ (r.input.spinful?"This calculation uses the spin-1/2 branch.":"This calculation uses the spinless branch; the staggered arrows represent only an abstract time-odd order parameter.")+"</p><div class=\"sax-pair\"><section><h5>Input k in reciprocal-lattice fractions</h5>"+math(k.k)+"</section><section><h5>First arrival at -k</h5>"+math(k.partner)+'</section></div>'+table("Integer condition for each component",["Component","Is 2k an integer?"],['x','y','z'].map((axis,i)=>[axis,yes(k.axisInvariant[i])]))+"<p>Returns to the same k fiber: <strong>"+yes(k.sameK)+'</strong>。</p>'+formula(r.steps[2].formula)+'<p>'+esc(k.description)+'</p>'+(k.sewingShift?"<p>Integer reciprocal vector G identifying -k with k:</p>"+math(k.sewingShift):"<p>There is no same-fiber identification here; the two different k spaces cannot be treated as a single space.</p>");
 if(stage>=2)html+="<h4>2. Track the cell boundary crossed by the half translation</h4><p>"+esc(t.convention)+'</p>'+table("Sites, unwrapped positions, and full-cell phase",["Mapping","Original position","Unreturned position","Cell index","Matrix-column coefficient"],t.siteMappings.map(s=>[esc(s.source)+' → '+esc(s.target),math(s.sourcePosition,true),math(s.unwrappedPosition,true),'<code data-math-ignore>'+esc(JSON.stringify(s.cellShift))+'</code>',math(s.coefficientAtK,true)]))+'<div class="sax-pair"><section><h5>S(k)</h5>'+math(t.atK)+'</section><section><h5>S(−k)</h5>'+math(t.atPartner)+"</section></div><p>Two successive half translations, S(k) squared:</p>"+math(t.squareAtK)+"<p>Retained full-cell phase:</p>"+math(t.fullCellPhase)+formula(r.steps[0].formula);
 if(stage>=3)html+="<h4>3. Conjugate again and use the returning fiber</h4><p>"+esc(a.convention)+"</p><p>Internal matrix J of time reversal:</p>"+math(a.thetaMatrix)+"<p>For this branch, Theta squared = "+esc(a.thetaSquare)+"。</p><div class=\"sax-pair\"><section><h5>Matrix part from k to -k</h5>"+math(a.atK)+"</section><section><h5>Matrix part returning from -k</h5>"+math(a.atPartner)+'</section></div>'+table("Complex-coefficient chain under successive actions",["Step","Exact state returned by Python"],[["Initial state in the input fiber",math(b.initialState)],["First action: conjugate the initial state",math(a.firstConjugate)],["First action: output in the partner fiber",math(a.firstState)],["Second conjugation of the entire intermediate state",math(a.secondConjugate)],["Second action: return to the original fiber",math(a.secondState)]])+formula(r.steps[1].formula)+(k.sameK?"<p>Same-fiber inner product <psi|A psi>:</p>"+math(a.sameKOverlap)+"<p>The selected state and its image are orthogonal: "+yes(a.sameKOrthogonal)+'。</p>':"<p>The same-fiber inner product is undefined here: the initial state and first output belong to different k spaces. Null must not be read as zero.</p>");
 if(stage>=4)html+="<h4>4. Check the three conditions separately</h4><p>"+esc(d.reason)+'</p>'+formula(r.steps[3].formula)+table("Conditional tests for this input",["Condition","Returned decision"],[["Returns to the same k",yes(d.sameK)],["The correct returning square is -I",yes(d.squareIsMinusOne)],["Pairing follows if H is additionally assumed to have A symmetry",yes(d.kramersConditional)],["Actual Hamiltonian symmetry",'<code data-math-ignore>'+esc(d.hamiltonianSymmetry)+'</code>'],["Actual material degeneracy",'<code data-math-ignore>'+esc(d.materialDegeneracy)+'</code>']])+"<p>Satisfying these conditions does not mean that this page has verified a material Hamiltonian or calculated bands.</p><p>Correct returning square across the two fibers:</p>"+math(a.returnSquare)+"<div class=\"sax-pair\"><section><h5>Incorrect comparison: directly square the same matrix, omitting conjugation</h5>"+math(a.wrongOrdinarySquare)+"</section><section><h5>Incorrect comparison: conjugate but reuse the same fiber matrix</h5>"+math(a.wrongSameFiberProduct)+"</section></div><p>At special k, an incorrect calculation may accidentally give the same value. Compare again at a generic longitudinal point or at 1/7.</p>"+(r.unitaryContrast.available?"<details data-sax-native=\"unitary\"><summary>Unitary G comparison for this input</summary><p>"+esc(r.unitaryContrast.description)+"</p><p>First examine the independent spin twofold rotation D(C2x), which does not rotate real space:</p>"+math(r.unitaryContrast.spinRotation)+"<p>Its tensor product with the same half-translation matrix S(k) gives the unitary G(k) for this input.</p>"+math(r.unitaryContrast.matrix)+'<p>G(k)²：</p>'+math(r.unitaryContrast.square)+'</details>':'<p>'+esc(r.unitaryContrast.reason)+'</p>')+"<p class=\"notice\"><strong>The following two counterexamples are fixed four-dimensional spin-1/2 models at Gamma and Z. They do not change with the k, initial state, or spinless setting above. All energies are dimensionless.</strong></p>"+r.counterexamples.map(exampleHTML).join('');
 return html;
}

