  try{if(typeof run!=='function')throw Error("The Python interface is unavailable. Reopen the lesson.");const result=await run('teaching_labs',input);if(!active()||ticket!==job)return;if(antitranslationModel(result).status!=='available'||identity(result.input)!==identity(input))throw Error("The returned result is incomplete or does not match this three-dimensional input.");state.result=result;state.input=clone(input);}
